import { z } from 'zod';

export const AddDepartmentDialogSchema = z.object({
    name: z.string().min(1, 'اسم القسم مطلوب').max(255),
    description: z.string().optional(),
});

export type AddDepartmentDialogFormValues = z.infer<typeof AddDepartmentDialogSchema>;

export const addDepartmentDialogDefaultValues: AddDepartmentDialogFormValues = {
    name: '',
    description: '',
};
