import type { ReactNode } from 'react';
import { ColumnDef, Row } from '@tanstack/react-table';
import { useNavigate } from 'react-router-dom';
import { Trash2, Power, PowerOff } from 'lucide-react';
import EditIcon from '@/components/icons/EditIcon';
import { Department } from '@/types/department.types';
import { cn } from '@/lib/utils';
import { apiDelete, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';

const headerCell =
    'text-sm px-4 py-3.5 text-primery-blue-600 font-semibold tracking-normal leading-relaxed bg-white-blue-100/90 border-b border-[#E8E7EA]';

const bodyCell = 'text-sm px-4 py-3.5 leading-relaxed align-middle';

function CellText({ children, className }: { children: ReactNode; className?: string }) {
    return (
        <span className={cn('text-[#4B5563] font-medium', className)} dir="auto">
            {children}
        </span>
    );
}

function display(v: unknown) {
    if (v == null || v === '') return '—';
    return String(v);
}

function StatusPill({ active }: { active: boolean }) {
    if (active) {
        return (
            <span
                className={cn(
                    'inline-flex items-center px-2.5 py-1 rounded-md text-xs font-semibold',
                    'bg-[#ECFDF5] text-[#047857] border border-[#A7F3D0]',
                )}
            >
                نشط
            </span>
        );
    }
    return (
        <span
            className={cn(
                'inline-flex items-center px-2.5 py-1 rounded-md text-xs font-semibold',
                'bg-[#F3F4F6] text-[#6B7280] border border-[#E5E7EB]',
            )}
        >
            معطّل
        </span>
    );
}

const ActionsCell = ({ row }: { row: Row<Department> }) => {
    const navigate = useNavigate();
    const id = row.original.id;
    const refresh = row.original.refreshTable;
    const isActive = row.original.is_active !== false;

    const btnClass =
        'inline-flex items-center justify-center rounded-lg p-2 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-primery-blue-400 focus-visible:ring-offset-1';

    const handleToggleActive = async () => {
        if (isActive) {
            const ok = window.confirm('تعطيل هذا القسم؟ سيُخفى من القوائم الافتراضية حتى يُعاد تفعيله.');
            if (!ok) return;
        }
        try {
            await apiPost({
                endpoint: `${endpoints.departments.update}${id}`,
                body: { is_active: !isActive },
            });
            toast.success(isActive ? 'تم تعطيل القسم' : 'تم تفعيل القسم', { className: 'font-cairo' });
            refresh?.();
        } catch (e: unknown) {
            const err = e as { response?: { data?: { msg?: string } } };
            toast.error(err.response?.data?.msg || 'تعذر تحديث حالة القسم', { className: 'font-cairo' });
        }
    };

    const handleDelete = async () => {
        const ok = window.confirm('حذف هذا القسم نهائياً؟ لا يمكن التراجع عن هذا الإجراء.');
        if (!ok) return;
        try {
            await apiDelete({ endpoint: `${endpoints.departments.delete}${id}` });
            toast.success('تم حذف القسم', { className: 'font-cairo' });
            refresh?.();
        } catch (e: unknown) {
            const err = e as { response?: { data?: { msg?: string } } };
            toast.error(err.response?.data?.msg || 'تعذر حذف القسم', { className: 'font-cairo' });
        }
    };

    return (
        <div className={cn(bodyCell, 'text-end')}>
            <div className="flex flex-row flex-wrap items-center justify-end gap-1">
                <button
                    type="button"
                    onClick={() => navigate(`/human-resources/department/${id}/edit`)}
                    className={cn(btnClass, 'text-primery-blue-500 hover:bg-primery-blue-50 hover:text-primery-blue-700')}
                    aria-label="تعديل القسم"
                >
                    <EditIcon width="18" height="18" />
                </button>
                <button
                    type="button"
                    onClick={() => void handleToggleActive()}
                    className={cn(
                        btnClass,
                        isActive
                            ? 'text-amber-600 hover:bg-amber-50'
                            : 'text-emerald-600 hover:bg-emerald-50',
                    )}
                    title={isActive ? 'تعطيل القسم' : 'تفعيل القسم'}
                    aria-label={isActive ? 'تعطيل القسم' : 'تفعيل القسم'}
                >
                    {isActive ? <PowerOff className="h-[18px] w-[18px]" /> : <Power className="h-[18px] w-[18px]" />}
                </button>
                <button
                    type="button"
                    onClick={() => void handleDelete()}
                    className={cn(btnClass, 'text-[#F04438] hover:bg-red-50')}
                    aria-label="حذف القسم"
                    title="حذف نهائي"
                >
                    <Trash2 className="h-[18px] w-[18px]" />
                </button>
            </div>
        </div>
    );
};

export const columns: ColumnDef<Department>[] = [
    {
        accessorKey: 'id',
        header: () => <div className={headerCell}>اسم القسم</div>,
        cell: ({ row }) => (
            <div className={bodyCell}>
                <span className="font-semibold text-primery-blue-800 tracking-normal">{display(row.original.name)}</span>
            </div>
        ),
    },
    {
        accessorKey: 'description',
        header: () => <div className={headerCell}>الوصف</div>,
        cell: ({ row }) => (
            <div className={bodyCell}>
                <CellText className="line-clamp-2 max-w-md">{display(row.original.description)}</CellText>
            </div>
        ),
    },
    {
        id: 'status',
        header: () => <div className={cn(headerCell, 'text-nowrap')}>الحالة</div>,
        cell: ({ row }) => (
            <div className={bodyCell}>
                <StatusPill active={row.original.is_active !== false} />
            </div>
        ),
    },
    {
        accessorKey: 'created_at',
        header: () => <div className={cn(headerCell, 'text-nowrap')}>تاريخ الإنشاء</div>,
        cell: ({ row }) => {
            const raw = row.original.created_at;
            let text = '—';
            if (raw) {
                const d = new Date(raw);
                if (!Number.isNaN(d.getTime())) {
                    text = new Intl.DateTimeFormat('ar-EG', {
                        dateStyle: 'short',
                        timeStyle: 'short',
                    }).format(d);
                }
            }
            return (
                <div className={bodyCell}>
                    <CellText className="tabular-nums text-xs">{text}</CellText>
                </div>
            );
        },
    },
    {
        id: 'actions',
        header: () => (
            <div className={cn(headerCell, 'text-center min-w-[140px] w-[140px]')}>إجراءات</div>
        ),
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
